# -*- coding: utf-8 -*-
# Catechism bank — the Iẓhār Q&A, bāb 2 (the governed word), items 1–25 (research/sources/izhar-sual-cevap.txt, Ottoman).
ITEMS = [
 {"n": 1, "q": {"tr": "Elfâz-ı mevzûa (bir mânâya vaz olunmuş lafızlar) kaç kısımdır?", "en": "How many kinds are the coined words, with respect to being governed?"},
  "a": {"tr": "İki: terkibde vâki olur veya olmaz; vâki olmayınca âmil olmadığı gibi ma'mûl de olmaz. Terkibde vâki olunca üç kısımdır: aslâ ma'mûl olmayan (harf ve Basralılara göre lâmsız emir); dâima ma'mûl olan (mutlak isim ve fiil-i muzâri); kendisinde ma'mûl olmamak asıl olup ikinci kısım mevkiinde olursa ma'mûl olan (أَنْ-i masdariyye ve cevâzimden sonra vâki olan fiil-i muzâri, ve cümle).", "en": "Two: they occur in a compound or not; outside a compound a word neither governs nor is governed. In a compound, three kinds: never governed (the particle, and the lām-less imperative for the Baṣrans); always governed (the noun absolutely, and the muḍāriʿ); governed only when it stands where the second kind stands, though its root is not to be governed (the muḍāriʿ after the maṣdar-أَنْ and the jāzims, and the sentence)."},
  "ar": ["الْأَلْفَاظُ الْمَوْضُوعَةُ"], "notes": ["al-mamul-wa-aqsamuh"]},
 {"n": 2, "q": {"tr": "Esmâ-i ef'âlin i'rabdan mahalli var mıdır?", "en": "Do the noun-verbs have a place in iʿrāb?"},
  "a": {"tr": "Esmâ-i ef'âl mübtedâ olup mâba'di fâil olarak haber makamına kâim olmakla mahallen merfû, veya masdar olmakla mahallen mansubdur — bazıları fiil mânâsına olduğu için i'rabdan mahalli yoktur dese de.", "en": "They are a mubtadaʾ whose doer, after it, stands in the khabar's place — so marfūʿ in place; or a maṣdar — so manṣūb in place; though some say that, bearing a verb's sense, they have no place at all."},
  "ar": ["أَسْمَاءُ الْأَفْعَالِ"], "notes": ["al-mamul-wa-aqsamuh", "ism-fil"]},
 {"n": 3, "q": {"tr": "Zamir-i faslın i'rabdan mahalli var mıdır?", "en": "Does the pronoun of separation have a place in iʿrāb?"},
  "a": {"tr": "Bazıları «i'rabdan mahalli olmayan isimdir» dese de, zamir-i fasl harf olmakla i'rabdan mahalli yoktur.", "en": "Though some call it a noun with no place, the pronoun of separation is a particle and so has no place in iʿrāb."},
  "ar": ["ضَمِيرُ الْفَصْلِ"], "notes": ["al-mamul-wa-aqsamuh", "damir-fasl"]},
 {"n": 4, "q": {"tr": "Cümle kaç kısımdır? Nelerdir?", "en": "How many kinds of sentence are there?"},
  "a": {"tr": "İki: fiiliyye ve ismiyye. Cümle-i fiiliyye: lafzan veya mânen fiil ile fâilinden mürekkeb olandır (ضَرَبَ زَيْدٌ، إِنْ تُكْرِمْنِي أُكْرِمْكَ؛ هَيْهَاتَ زَيْدٌ، أَقَائِمٌ الزَّيْدَانِ، أَفِي الدَّارِ زَيْدٌ). Cümle-i ismiyye: mübtedâ ve haberden veya âmil olan harfin ismi ve haberinden mürekkeb olandır (زَيْدٌ قَائِمٌ؛ إِنَّ زَيْدًا قَائِمٌ).", "en": "Two: verbal and nominal. The verbal sentence is composed of a verb — in wording or in sense — and its doer (ضَرَبَ زَيْدٌ، إِنْ تُكْرِمْنِي أُكْرِمْكَ؛ هَيْهَاتَ زَيْدٌ، أَقَائِمٌ الزَّيْدَانِ، أَفِي الدَّارِ زَيْدٌ). The nominal sentence is composed of a mubtadaʾ and khabar, or of a governing particle's ism and khabar (زَيْدٌ قَائِمٌ؛ إِنَّ زَيْدًا قَائِمٌ)."},
  "ar": ["الْمُرَكَّبَةُ مِنَ الْفِعْلِ لَفْظًا أَوْ مَعْنًى وَفَاعِلِهِ", "الْمُرَكَّبَةُ مِنَ الْمُبْتَدَإِ وَالْخَبَرِ أَوْ مِنِ اسْمِ الْحَرْفِ الْعَامِلِ وَخَبَرِهِ"], "notes": ["al-madi-wal-jumla-mamulayn", "anwa-al-jumal"]},
 {"n": 5, "q": {"tr": "İ'rabdan mahalli olan ve olmayan cümleler nelerdir?", "en": "Which sentences have a place in iʿrāb, and which have none?"},
  "a": {"tr": "Mahalli olanlar yedidir: lafzı murad olunan; masdar mânâsı murad olunan; haber vâki olan; mef'ûl vâki olan; fâ-i cezâ ve izâ-i müfâcât ile câzim şarta cevap olan; hâl vâki olan; tâbi vâki olan. Mübtedânın ve إِنَّ bâbının haberi olan cümle mahallen merfû; كَانَ ve كَادَ bâbının haberi, عَلِمَ'nin ikinci ve أَعْلَمَ'nin üçüncü mef'ûlü, kendisinden ta'lîk vâki olan ve hâl olan cümle mahallen mansub; fâ ve izâdan sonra cevap olan mahallen meczûm; tâbi olan cümle metbûunun i'rabını alır. Mahalli olmayanlar yedidir: ibtidâiyye, sıla, i'tirâziyye, tefsiriyye, kaseme cevap, câzim olmayan şarta cevap, mahalli olmayana tâbi olan.", "en": "With a place, seven: one whose wording is quoted; one read as a maṣdar; one standing as khabar; as object; as answer to a jāzim condition with the fāʾ or the إِذَا of surprise; as ḥāl; as follower. The khabar of a mubtadaʾ or of إِنَّ is marfūʿ in place; the khabar of كَانَ and كَادَ, the second object of عَلِمَ and third of أَعْلَمَ, the suspended clause and the ḥāl clause are manṣūb in place; the answer after the fāʾ or إِذَا is majzūm in place; a follower takes its antecedent's iʿrāb. Without a place, seven: the opening sentence, the ṣila, the parenthesis, the explanatory, the oath's answer, the answer of a non-jāzim condition, and what follows a sentence without a place."},
  "ar": ["الْجُمَلُ الَّتِي لَهَا مَحَلٌّ مِنَ الْإِعْرَابِ"], "notes": ["mawadi-irab-al-jumla", "anwa-al-jumal"]},
 {"n": 6, "q": {"tr": "Ma'mûl kaç kısımdır? Ma'mûl-i merfû kaçtır?", "en": "How many kinds of governed word are there, and how many marfūʿ ones?"},
  "a": {"tr": "Ma'mûl bi'l-asâle ve bi't-tebaiyye olmak üzere iki; bi'l-asâle dörttür: merfû, mansub, mecrûr, meczûm. Ma'mûl-i merfû dokuzdur: fâil, nâib-i fâil, mübtedâ, haber, كَانَ bâbının ismi, إِنَّ bâbının haberi, cins nefyi için olan لَا'nın haberi, لَيْسَ'ye benzeyen مَا ve لَا'nın ismi, nevâsıb ve cevâzimden hâlî fiil-i muzâri.", "en": "Governed in its own right or by following; in its own right, four: marfūʿ, manṣūb, majrūr, majzūm. The marfūʿ are nine: the doer, the deputy doer, the mubtadaʾ, the khabar, the ism of كَانَ, the khabar of إِنَّ, the khabar of the genus-denying لَا, the ism of مَا and لَا like لَيْسَ, and the muḍāriʿ free of nāṣib and jāzim."},
  "ar": ["الْمَعْمُولُ بِالْأَصَالَةِ", "الْمَعْمُولُ بِالتَّبَعِيَّةِ"], "notes": ["al-mamul-wa-aqsamuh", "al-marfuat-al-fail-wa-naibuh"]},
 {"n": 7, "q": {"tr": "Fâilin tarifi nedir?", "en": "How is the doer defined?"},
  "a": {"tr": "Malum tâm fiil veya onun mânâsına olan kendisine isnad olunandır (ضَرَبَ زَيْدٌ، أَقَائِمٌ الزَّيْدَانِ، هَيْهَاتَ زَيْدٌ).", "en": "That to which an active complete verb, or what bears its sense, is predicated (ضَرَبَ زَيْدٌ، أَقَائِمٌ الزَّيْدَانِ، هَيْهَاتَ زَيْدٌ)."},
  "ar": ["مَا أُسْنِدَ إِلَيْهِ الْفِعْلُ التَّامُّ الْمَعْلُومُ أَوْ مَا شَابَهَهُ"], "notes": ["al-marfuat-al-fail-wa-naibuh", "fail"]},
 {"n": 8, "q": {"tr": "Nâib-i fâilin tarifi nedir?", "en": "How is the deputy doer defined?"},
  "a": {"tr": "Meçhul tâm fiil veya onun mânâsına olan kendisine isnad olunandır (ضُرِبَ زَيْدٌ، أَمَضْرُوبٌ الزَّيْدَانِ).", "en": "That to which a passive complete verb, or what bears its sense, is predicated (ضُرِبَ زَيْدٌ، أَمَضْرُوبٌ الزَّيْدَانِ)."},
  "ar": ["مَا أُسْنِدَ إِلَيْهِ الْفِعْلُ التَّامُّ الْمَجْهُولُ أَوْ مَا بِمَعْنَاهُ"], "notes": ["al-marfuat-al-fail-wa-naibuh", "naib-al-fail"]},
 {"n": 9, "q": {"tr": "Fâil ve nâib-i fâil kaç kısımdır?", "en": "How many kinds of doer and deputy doer are there?"},
  "a": {"tr": "İki: zamir ve ism-i zâhir. Zamir de iki: müstetir (gizli) ve bâriz (açık). Müstetir de iki: vâcibü'l-istitâr (zamiri açığa çıkarmak câiz olmadığından; âmil ancak zamire isnad olunur) ve câizü'l-istitâr (âmil bazen zamire bazen ism-i zâhire isnad olunur).", "en": "Two: a pronoun or an overt noun. The pronoun is hidden or apparent. The hidden one is either necessarily hidden — it may not be brought out, and the governor is predicated only of a pronoun — or optionally hidden, where the governor may take a pronoun or an overt noun."},
  "ar": ["الْمُسْتَتِرُ وُجُوبًا", "الْمُسْتَتِرُ جَوَازًا"], "notes": ["al-fail-al-mudmar-al-mustatir-wujuban"]},
 {"n": 10, "q": {"tr": "Vâcibü'l-istitâr nerelerde olur?", "en": "Where is the pronoun necessarily hidden?"},
  "a": {"tr": "Mâzînin gayrısında müfred müzekker muhâtab, mütekellim vahde ve mütekellim maa'l-gayrda; emir mânâsına olan esmâ-i ef'âlde; kühl meselesinin gayrı ism-i tafdîlde; zâhirî fâilinde amel şartı bulunmadığında ism-i fâil, ism-i mef'ûl, ism-i müsteâr, ism-i mensûb, sıfat-ı müşebbehe ve zarf-ı müstakarda; ism-i fâil ve ism-i mef'ûlün tesniye ve cem'-i sâlimlerinde; fiil olan عَدَا ve خَلَا'da ve istisnâ bâbındaki مَا عَدَا، مَا خَلَا، لَيْسَ، لَا يَكُونُ'da.", "en": "In the non-past second person masculine singular and the two first persons; in the command noun-verbs; in the ism tafḍīl except the kohl case; in the ism fāʿil, ism mafʿūl, borrowed noun, nisba noun, ṣifa mushabbaha and settled ẓarf when the condition for an overt doer is absent; in the dual and sound plural of the ism fāʿil and ism mafʿūl; in the verbs عَدَا and خَلَا and in مَا عَدَا، مَا خَلَا، لَيْسَ، لَا يَكُونُ of exception."},
  "ar": ["الضَّمِيرُ الْمُسْتَتِرُ وُجُوبًا"], "notes": ["al-fail-al-mudmar-al-mustatir-wujuban"]},
 {"n": 11, "q": {"tr": "Câizü'l-istitâr nerelerde olur?", "en": "Where is the pronoun optionally hidden?"},
  "a": {"tr": "Müfred müzekker gâib ve müfred müennes gâibede; amel şartı bulunduğunda, tesniye ve cem'-i müzekkerin gayrı şibh-i fiilde (ism-i fâil, ism-i mef'ûl, sıfat-ı müşebbehe, masdar, ism-i tafdîl).", "en": "In the third person masculine and feminine singular; and, when the condition of governing holds, in the verb-like words other than their dual and masculine plural (ism fāʿil, ism mafʿūl, ṣifa mushabbaha, maṣdar, ism tafḍīl)."},
  "ar": ["الضَّمِيرُ الْمُسْتَتِرُ جَوَازًا"], "notes": ["al-mustatir-jawazan"]},
 {"n": 12, "q": {"tr": "Zamîr-i bâriz-i muttasıl nelerdir?", "en": "Which are the apparent attached pronouns?"},
  "a": {"tr": "Fiillerin tesniyesinde elif; cem'-i müzekkerinde vâv; cem'-i müennesinde nûn; fiil-i mâzînin müfred müzekker muhâtab, müfred müennes muhâtaba ve mütekellim vahdesinde tâ; mütekellim maa'l-gayrında نَا; mâzînin gayrısında müfred müennes muhâtabada yâ.", "en": "The alif in the dual of verbs; the wāw in the masculine plural; the nūn in the feminine plural; the tāʾ in the māḍī's second person singular, masculine and feminine, and its first person singular; نَا in the first person plural; the yāʾ in the non-past second person feminine singular."},
  "ar": ["الضَّمِيرُ الْبَارِزُ الْمُتَّصِلُ"], "notes": ["al-bariz-al-muttasil"]},
 {"n": 13, "q": {"tr": "Âmil ism-i zâhire isnad ettiği zaman nasıl gelir?", "en": "How does the governor come when predicated of an overt noun?"},
  "a": {"tr": "İsm-i zâhir hakikî müennes, insandan, müfred veya tesniye, âmiline muttasıl ve âmili mutasarrıf fiil ise âmilin müennes gelmesi vâcibdir (ضَرَبَتْ هِنْدٌ). Bu şartlardan biri bulunmazsa müzekker ve müennes gelmesi câizdir (طَلَعَتْ / طَلَعَ الشَّمْسُ؛ جَاءَتْ / جَاءَ الْقَاضِيَ الْيَوْمَ امْرَأَةٌ). İsm-i zâhir cem'-i müzekker-i sâlimin gayrı bir cem' ise âmilin müfred müennes veya müfred müzekker gelmesi câizdir (جَاءَتْ / جَاءَ الرِّجَالُ). Cem'-i müzekker-i sâlim ise müfred müzekker gelmesi vâcibdir (ضَرَبَ الزَّيْدُونَ).", "en": "If the noun is a real feminine, human, singular or dual, joined to its governor, and the governor is a conjugating verb, the governor must be feminine (ضَرَبَتْ هِنْدٌ). Failing one of these, either gender is allowed (طَلَعَتْ / طَلَعَ الشَّمْسُ؛ جَاءَتْ / جَاءَ الْقَاضِيَ الْيَوْمَ امْرَأَةٌ). With a plural other than the sound masculine, the governor may be feminine singular or masculine singular (جَاءَتْ / جَاءَ الرِّجَالُ). With a sound masculine plural it must be masculine singular (ضَرَبَ الزَّيْدُونَ)."},
  "ar": ["ضَرَبَتْ هِنْدٌ", "ضَرَبَ الزَّيْدُونَ"], "notes": ["al-fail-al-muzhar-wa-tanith-amilih"]},
 {"n": 14, "q": {"tr": "Âmil zamire isnad ettiği zaman nasıl olur?", "en": "How does the governor come when predicated of a pronoun?"},
  "a": {"tr": "Müfred müennese râci zamire isnad ederse müfred müennes gelmesi vâcibdir (زَيْنَبُ خَرَجَتْ). Cem'-i müzekker-i sâlime râci zamire isnad ederse cem'-i müzekker gelmesi vâcibdir (الْمُسْلِمُونَ قَامُوا). Cem'-i müzekker-i mükesser-i âkile râci ise müfred müennes veya cem'-i müzekker câizdir (الرِّجَالُ جَاءَتْ / جَاءُوا). Cem'-i müennes-i sâlime veya cem'-i müennes-i mükessere râci ise müfred müennes veya cem'-i müennes câizdir (الْمُسْلِمَاتُ ذَهَبَتْ / ذَهَبْنَ؛ الْأَشْجَارُ قُطِعَتْ / قُطِعْنَ).", "en": "Referring to a feminine singular, the governor must be feminine singular (زَيْنَبُ خَرَجَتْ). Referring to a sound masculine plural, masculine plural (الْمُسْلِمُونَ قَامُوا). Referring to a rational masculine broken plural, feminine singular or masculine plural (الرِّجَالُ جَاءَتْ / جَاءُوا). Referring to a sound or broken feminine plural, feminine singular or feminine plural (الْمُسْلِمَاتُ ذَهَبَتْ / ذَهَبْنَ؛ الْأَشْجَارُ قُطِعَتْ / قُطِعْنَ)."},
  "ar": ["الْمُسْلِمُونَ قَامُوا"], "notes": ["al-fail-al-muzhar-wa-tanith-amilih", "al-jumu-wa-tanith-amiliha"]},
 {"n": 15, "q": {"tr": "Müennesin tarifi nedir? Te'nis alâmeti kaçtır?", "en": "How is the feminine defined, and how many signs of femininity are there?"},
  "a": {"tr": "Müennes: lafzan veya takdiren kendisinde te'nis alâmeti olandır. Alâmeti üçtür: üzerine hâ diye durulan tâ (ظُلْمَة، شَمْس), elif-i maksûre (حُبْلَى), elif-i memdûde (حَمْرَاء).", "en": "The feminine is that which carries a sign of femininity, stated or implied. The signs are three: the tāʾ paused on as hāʾ (ظُلْمَة، شَمْس), the shortened alif (حُبْلَى), the lengthened alif (حَمْرَاء)."},
  "ar": ["مَا فِيهِ عَلَامَةُ التَّأْنِيثِ لَفْظًا أَوْ تَقْدِيرًا"], "notes": ["al-muannath-wa-alamatuh"]},
 {"n": 16, "q": {"tr": "Müennes-i hakikî ve lafzî nedir?", "en": "What are the real and the formal feminine?"},
  "a": {"tr": "Müennes-i hakikî: karşısında hayat sahiplerinden müzekkeri olandır (امْرَأَة، نَاقَة). Müennes-i lafzî: karşısında hayat sahiplerinden müzekkeri olmayandır.", "en": "The real feminine has, among living things, a male counterpart (امْرَأَة، نَاقَة). The formal feminine has none."},
  "ar": ["مَا بِإِزَائِهِ ذَكَرٌ مِنَ الْحَيَوَانِ", "مَا لَيْسَ بِإِزَائِهِ ذَكَرٌ مِنَ الْحَيَوَانِ"], "notes": ["al-jumu-wa-tanith-amiliha", "al-muannath-wa-alamatuh"]},
 {"n": 17, "q": {"tr": "Cem'-i mükesser ve cem'-i müzekker-i sâlimin tarifi nedir?", "en": "How are the broken plural and the sound masculine plural defined?"},
  "a": {"tr": "Cem'-i mükesser: müfredinin sîgası değişendir (رِجَال). Cem'-i müzekker-i sâlim: müfredinin âhirine mâkabli mazmum vâv veya mâkabli meksûr yâ ve izâfetin gayrısında meftûh nûn bitişendir (مُسْلِمُونَ، مُسْلِمِينَ).", "en": "The broken plural is that whose singular's form is changed (رِجَال). The sound masculine plural is that to whose singular is joined a wāw after a ḍamma or a yāʾ after a kasra, and a nūn with fatḥa outside annexation (مُسْلِمُونَ، مُسْلِمِينَ)."},
  "ar": ["مَا تَغَيَّرَ صِيغَةُ مُفْرَدِهِ", "مَا لَحِقَ آخِرَ مُفْرَدِهِ وَاوٌ مَضْمُومٌ مَا قَبْلَهَا أَوْ يَاءٌ مَكْسُورٌ مَا قَبْلَهَا وَنُونٌ مَفْتُوحَةٌ فِي غَيْرِ الْإِضَافَةِ"], "notes": ["al-jumu-wa-tanith-amiliha", "jam-mudhakkar-salim", "jam-taksir"]},
 {"n": 18, "q": {"tr": "Cem'-i müennes-i sâlimin tarifi nedir?", "en": "How is the sound feminine plural defined?"},
  "a": {"tr": "Müfredinin âhirine elif ve tâ bitişendir (مُسْلِمَات).", "en": "That to whose singular an alif and a tāʾ are joined (مُسْلِمَات)."},
  "ar": ["مَا لَحِقَ آخِرَ مُفْرَدِهِ أَلِفٌ وَتَاءٌ"], "notes": ["al-jumu-wa-tanith-amiliha", "jam-muannath-salim"]},
 {"n": 19, "q": {"tr": "Tesniyenin tarifi nedir?", "en": "How is the dual defined?"},
  "a": {"tr": "Müfredinin âhirine mâkabli meftûh elif veya yâ ve izâfetin gayrısında meksûr nûn bitişendir.", "en": "That to whose singular is joined an alif or a yāʾ after a fatḥa, and a nūn with kasra outside annexation."},
  "ar": ["مَا لَحِقَ آخِرَ مُفْرَدِهِ أَلِفٌ أَوْ يَاءٌ مَفْتُوحٌ مَا قَبْلَهَا وَنُونٌ مَكْسُورَةٌ فِي غَيْرِ الْإِضَافَةِ"], "notes": ["al-jumu-wa-tanith-amiliha", "al-muthanna"]},
 {"n": 20, "q": {"tr": "Mübtedâ kaç kısımdır? Tarifleri nelerdir?", "en": "How many kinds of mubtadaʾ are there, and how are they defined?"},
  "a": {"tr": "İki. Birincisi: lafzî âmillerden soyulmuş müsnedün ileyh olup isim veya isim te'vîlinde olandır (زَيْدٌ قَائِمٌ؛ حَقٌّ أَنَّكَ قَائِمٌ). İkincisi: zâhirî fâilini ref' edici olduğu hâlde istifham veya nefiy kelimesinden sonra vâki olan sıfattır (أَقَائِمٌ الزَّيْدَانِ؛ مَا قَائِمٌ الزَّيْدُونَ).", "en": "Two. The first: the noun, or what is construed as a noun, stripped of wording governors and predicated-of (زَيْدٌ قَائِمٌ؛ حَقٌّ أَنَّكَ قَائِمٌ). The second: an adjective after a question or negation word, raising an overt doer (أَقَائِمٌ الزَّيْدَانِ؛ مَا قَائِمٌ الزَّيْدُونَ)."},
  "ar": ["الِاسْمُ الْمُؤَوَّلُ بِهِ الْمُسْنَدُ إِلَيْهِ الْمُجَرَّدُ عَنِ الْعَوَامِلِ اللَّفْظِيَّةِ", "الصِّفَةُ الْوَاقِعَةُ بَعْدَ كَلِمَةِ الِاسْتِفْهَامِ أَوِ النَّفْيِ رَافِعَةً لِظَاهِرٍ"], "notes": ["al-mubtada-wa-nawah", "mubtada-khabar"]},
 {"n": 21, "q": {"tr": "Mübtedâya haber lâzım mıdır?", "en": "Does the mubtadaʾ need a khabar?"},
  "a": {"tr": "Birinci kısım mübtedâya haber lâzımdır; ikinci kısım fiil makamına kâim olduğundan haber lâzım değildir, fâili haber makamına kâimdir.", "en": "The first kind needs one; the second, standing in a verb's place, needs none — its doer stands in the khabar's place."},
  "ar": ["أَقَائِمٌ الزَّيْدَانِ"], "notes": ["al-mubtada-wa-nawah"]},
 {"n": 22, "q": {"tr": "Mübtedânın şartı nedir?", "en": "What is the condition of the mubtadaʾ?"},
  "a": {"tr": "Ma'rife veya hususîleşmiş nekre olmaktır (زَيْدٌ قَائِمٌ؛ وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ).", "en": "To be definite, or an indefinite made particular (زَيْدٌ قَائِمٌ؛ وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ)."},
  "ar": ["وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ"], "notes": ["al-mubtada-wa-nawah"]},
 {"n": 23, "q": {"tr": "Haberin tarifi nedir?", "en": "How is the khabar defined?"},
  "a": {"tr": "Fiil ve mânâ-yı fiilin gayrısı olduğu hâlde müsned bih olup lafzî âmillerden soyulandır (زَيْدٌ قَائِمٌ'deki قَائِمٌ).", "en": "What is predicated — being other than a verb or a verb-sense word — and stripped of wording governors (قَائِمٌ in زَيْدٌ قَائِمٌ)."},
  "ar": ["الْمُجَرَّدُ عَنِ الْعَوَامِلِ اللَّفْظِيَّةِ الْمُسْنَدُ بِهِ غَيْرُ الْفِعْلِ وَمَعْنَاهُ"], "notes": ["khabar-al-mubtada-wa-ahkamuh"]},
 {"n": 24, "q": {"tr": "Haberin taaddüdü câiz midir?", "en": "May the khabar be multiplied?"},
  "a": {"tr": "Câizdir: زَيْدٌ قَائِمٌ عَالِمٌ فَاضِلٌ gibi.", "en": "Yes: زَيْدٌ قَائِمٌ عَالِمٌ فَاضِلٌ."},
  "ar": ["زَيْدٌ قَائِمٌ عَالِمٌ فَاضِلٌ"], "notes": ["khabar-al-mubtada-wa-ahkamuh"]},
 {"n": 25, "q": {"tr": "Haber cümle olur mu?", "en": "Can the khabar be a sentence?"},
  "a": {"tr": "Bazen cümle-i haberiyye (fiiliyye ve ismiyye) olur; o zaman zamir-i şandan haber olmadığı müddetçe cümlede mübtedâya râci bir zamir lâzım gelir (زَيْدٌ أَبُوهُ قَائِمٌ، قَامَ أَبُوهُ). Karine olduğunda bu zamirin hazfi câizdir (الْبُرُّ الْكُرُّ بِسِتِّينَ — mahzûf zamir مِنْهُ'dur).", "en": "Sometimes it is a declarative sentence, verbal or nominal; then, unless it is the khabar of a pronoun of the matter, a pronoun returning to the mubtadaʾ is needed (زَيْدٌ أَبُوهُ قَائِمٌ، قَامَ أَبُوهُ). With a clue the pronoun may be dropped (الْبُرُّ الْكُرُّ بِسِتِّينَ — the dropped pronoun is مِنْهُ)."},
  "ar": ["زَيْدٌ أَبُوهُ قَائِمٌ"], "notes": ["khabar-al-mubtada-wa-ahkamuh", "anwa-al-khabar"]},
]
